/* ---------- Projets : temps forts et textile ---------- */
const pol=(a,b,r,deg)=>[a+r*Math.cos(deg*Math.PI/180),b+r*Math.sin(deg*Math.PI/180)];
const f1=n=>n.toFixed(1);
function sector(cx,cy,r,a1,a2,c){const p=pol(cx,cy,r,a1),q=pol(cx,cy,r,a2);return `<path class="${c}" d="M${cx} ${cy} L${f1(p[0])} ${f1(p[1])} A${r} ${r} 0 ${a2-a1>180?1:0} 1 ${f1(q[0])} ${f1(q[1])} Z"/>`}
function annular(cx,cy,r1,r2,a1,a2,c){const a=pol(cx,cy,r2,a1),b=pol(cx,cy,r2,a2),d=pol(cx,cy,r1,a2),e=pol(cx,cy,r1,a1);return `<path class="${c}" d="M${f1(a[0])} ${f1(a[1])} A${r2} ${r2} 0 0 1 ${f1(b[0])} ${f1(b[1])} L${f1(d[0])} ${f1(d[1])} A${r1} ${r1} 0 0 0 ${f1(e[0])} ${f1(e[1])} Z"/>`}
function wheel(cx,cy,r,n,cf){let o="";for(let i=0;i<n;i++)o+=sector(cx,cy,r,-90-180/n+i*360/n,-90+180/n+i*360/n,cf(i));return o+`<circle class="of" cx="${cx}" cy="${cy}" r="${r*.08}"/>`}
const can=(x,y,w,h,c="of")=>`<rect class="${c}" x="${x}" y="${y}" width="${w}" height="${h}"/><ellipse class="${c}" cx="${x+w/2}" cy="${y}" rx="${w/2}" ry="${w*.14}"/>`;
const bubble=(x,y,w,h,t,c="of")=>`<path class="${c}" d="M${x} ${y} h${w} v${h} h-${w*.6} l-10 12 l2 -12 h-${w*.4-8} Z" style="stroke-linejoin:round"/><text class="l" x="${x+w/2}" y="${y+h/2+4}" text-anchor="middle">${t}</text>`;
const TANK="M80 20 L98 20 Q120 50 142 20 L160 20 L160 58 L174 70 L174 148 L66 148 L66 70 L80 58 Z";
const TSHIRT="M84 16 L100 12 Q120 30 140 12 L156 16 L206 42 L190 70 L172 60 L172 150 L68 150 L68 60 L50 70 L34 42 Z";
function fishHoles(){const pts=[];for(let k=0;k<12;k++){const a=(k*30+15)*Math.PI/180;pts.push([110+62*Math.cos(a),80+36*Math.sin(a)])}return pts}
function weave(x,y,cols,rows,s,cf){let o="";for(let c=0;c<cols;c++)o+=`<rect class="vb" x="${x+c*s*2+s*.25}" y="${y-4}" width="${s*1.5}" height="${rows*s*2+8}" style="stroke-width:1"/>`;
 for(let r=0;r<rows;r++){o+=`<rect class="${cf(r)}" x="${x-6}" y="${y+r*s*2+s*.3}" width="${cols*s*2+12}" height="${s*1.4}" style="stroke-width:1"/>`;for(let c=0;c<cols;c++)if((r+c)%2)o+=`<rect class="vb" x="${x+c*s*2+s*.25}" y="${y+r*s*2+s*.1}" width="${s*1.5}" height="${s*1.8}" style="stroke-width:1"/>`}return o}
const cat=(final)=>`<circle class="of" cx="120" cy="84" r="58"/><polygon class="tpf" points="72,48 80,8 108,34"/><polygon class="tpf" points="168,48 160,8 132,34"/><circle class="hole2" cx="98" cy="74" r="10"/><circle class="hole2" cx="142" cy="74" r="10"/><polygon class="pk" points="110,96 130,96 120,108"/>`+(final?`<rect class="ink" x="70" y="102" width="34" height="4"/><rect class="ink" x="70" y="112" width="34" height="4"/><rect class="ink" x="136" y="102" width="34" height="4"/><rect class="ink" x="136" y="112" width="34" height="4"/><circle class="vr" cx="86" cy="126" r="6"/><circle class="vr" cx="154" cy="126" r="6"/>`:`<rect class="ink" x="70" y="102" width="34" height="4"/>`);
const kite=(cx,cy,ang,c)=>{const p=(r,d)=>pol(cx,cy,r,ang+d).map(f1).join(",");return `<polygon class="${c}" points="${cx},${cy} ${p(36,-28)} ${p(64,0)} ${p(36,28)}"/>`};
const needle=(x1,y1,x2,y2)=>{const a=Math.atan2(y2-y1,x2-x1),n=[Math.sin(a)*3,-Math.cos(a)*3];return `<polygon class="of" points="${x1},${y1} ${f1(x2+n[0])},${f1(y2+n[1])} ${f1(x2-n[0])},${f1(y2-n[1])}"/><ellipse class="hole" cx="${f1(x2-Math.cos(a)*8)}" cy="${f1(y2-Math.sin(a)*8)}" rx="4" ry="1.5" transform="rotate(${f1(a*180/Math.PI)} ${f1(x2-Math.cos(a)*8)} ${f1(y2-Math.sin(a)*8)})" style="stroke:var(--ink);stroke-width:1"/>`};

