Object.assign(D,{
"masque-formes":{
 notions:[["Mathématiques","Reconnaître, nommer et classer des formes planes : rond, triangle, carré, rectangle","Étapes 1 et 5"],["Mathématiques","Dénombrer les formes de chaque sorte","Étape 5"],["Arts plastiques","Composer une figure avec des formes ; couleurs, contrastes","Étapes 2 et 3"],["Langage et français","Décrire sa production avec une phrase complète et le nombre","Étape 5"]],
 remplace:"Une séance de tri et de reconnaissance des formes avec des blocs logiques. Les formes sont les mêmes, mais l’enfant doit les choisir pour représenter quelque chose : une oreille pointue appelle un triangle.",
 phase:"Réinvestissement du vocabulaire des formes",
 gain:["Choisir une forme pour une fonction oblige à regarder ses propriétés : pointes, côtés, arrondi.","Le vocabulaire est utilisé pour de vrai, devant la classe, au moment du défilé.","Les intrus du tri (ovale, goutte) font discuter ce qu’est vraiment un rond.","La production est portée et montrée lors du carnaval."],
 concep:[["« Un triangle à l’envers n’est plus un triangle. »","Les oreilles sont des triangles pointe en haut, le nez un triangle pointe en bas : c’est la même forme."],["« Un carré et un rectangle, c’est pareil. »","On compare en superposant les côtés : le carré a ses quatre côtés de même longueur ; les rectangles de la barquette ont deux côtés plus longs que les deux autres. Attention pour l’enseignant : le carré est un rectangle particulier, on ne dit donc pas aux enfants qu’« un carré n’est pas un rectangle »."],["« Rond, c’est tout ce qui est arrondi. »","L’ovale et la goutte vont dans la boîte des intrus."]],
 relances:["Quelle forme as-tu choisie pour les oreilles ? Pourquoi ?","Combien de triangles sur ton masque ?","Si je tourne le triangle, est-ce encore un triangle ?"],
 vocab:["rond","triangle","carré","rectangle","pointe","côté","grand","petit"],
 trace:"<p><b>Photo du masque et dictée à l’adulte.</b></p><p>Mon masque de chat a 2 triangles pour les oreilles, 1 triangle pour le nez et 4 rectangles pour les moustaches.</p>",
 aide:["Modèle à reproduire posé à côté.","Deux sortes de formes seulement."],
 expert:["Un animal fait seulement de triangles.","Décrire son masque à un camarade qui doit le refaire sans le voir."]},
"carte-a-coudre":{
 notions:[["Mathématiques","Algorithme dessus, dessous ; suivre une suite ordonnée de trous (nombres en GS)","Étapes 3 et 4"],["Langage et français","Vocabulaire spatial : devant, derrière, dessus, dessous","Étapes 3 et 5"],["Arts plastiques","Dessiner avec un fil ; geste précis et coordonné","Étape 4"]],
 remplace:"Les ateliers de motricité fine et de repérage spatial, souvent menés avec des fiches de graphisme. Le fil oblige à vivre l’alternance avec les mains et à nommer la position de l’aiguille.",
 phase:"Atelier autonome répété",
 gain:["Le vocabulaire spatial est vécu : l’aiguille est devant ou derrière la carte.","L’erreur se voit : un lacet qui fait le tour du bord ne dessine rien devant.","L’atelier se réutilise toute l’année, l’enfant progresse en autonomie.","C’est l’entrée dans la couture, prolongée en élémentaire."],
 concep:[["« Pour coudre, on tourne autour. »","Le lacet qui enroule le bord ne dessine rien devant : il faut traverser la carte."],["« Devant et derrière, c’est pareil. »","On retourne la carte : les traits de derrière sont dans les vides de devant."]],
 relances:["Ton aiguille est-elle devant ou derrière ?","Quel est le prochain trou ?","Que vois-tu devant ? Et derrière ?"],
 vocab:["devant","derrière","dessus","dessous","trou","fil","aiguille","nœud","contour"],
 trace:"<p><b>Photo de la carte, devant et derrière, et dictée.</b></p><p>J’ai cousu le poisson. Mon aiguille passe dessus, dessous, dessus, dessous.</p>",
 aide:["Carte de 6 trous.","L’adulte tient la carte."],
 expert:["Carte numérotée de 20 trous.","Deux couleurs de lacet."]},
"chevalet-prenom":{
 notions:[["Mathématiques","Mesurer et tracer en cm, placer le 0 ; partager une longueur en parts égales (pliage en CP)","Étape 1"],["Mathématiques","Reconnaître un solide : le prisme, ses faces et ses arêtes (CE2)","Étapes 2 et 5"],["Langage et français","Écrire son prénom avec une majuscule, lisible de loin","Étape 3"],["Arts plastiques","Se présenter par un graphisme personnel","Étape 4 et séance 2"]],
 remplace:"La première séance de mesure de l’année et l’étiquette-prénom de rentrée, préparée d’habitude par l’enseignant. L’élève fabrique sa propre étiquette en mesurant, ce qui sert d’évaluation diagnostique.",
 phase:"Rentrée : évaluation diagnostique en action",
 gain:["Dès le premier jour, on voit qui sait placer le 0 de la règle et qui écrit lisiblement.","Des parts inégales se voient tout de suite : le chevalet penche ou ne ferme pas.","Écrire pour être lu de loin donne un sens à la taille et à l’épaisseur des lettres.","Le graphisme personnel lance les échanges de rentrée."],
 concep:[["« Pour faire 4 parts égales, je trace 3 traits au hasard. »","Le chevalet penche ou ne ferme pas : on mesure ou on plie."],["« La règle commence au bord. »","Les traits ne tombent pas au même endroit que chez le voisin : on vérifie le 0."],["« J’écris avant de plier. »","Un des prénoms se retrouve à l’envers : il faut anticiper le pliage."]],
 relances:["Comment être sûr que tes 4 parts sont égales ?","Ton voisin, au fond de la classe, peut-il lire ?","Que raconte ton dessin sur toi ?"],
 vocab:["part","égal","pli","face","arête","prisme","majuscule","lisible"],
 trace:"<p>Pour partager une bande de 24 cm en 4 parts égales, je trace des traits à 6, 12 et 18 cm.</p><p>Mon chevalet est un prisme : il a des faces planes et des arêtes.</p>",
 aide:["Traits déjà tracés.","Pliage à la place de la mesure."],
 expert:["Bande de 30 cm : calculer où tracer les traits.","Compter les faces et les arêtes du chevalet."]},
"chamboule-tout":{
 notions:[["Mathématiques","Additionner plusieurs nombres ; calcul mental en regroupant (5 + 5 = 10)","Étape 5 et séance 3"],["Mathématiques","Mesurer une ligne courbe avec une bande ; mesurer en cm","Étape 1"],["Mathématiques","Solides : le cylindre ; son habillage déroulé est un rectangle","Étapes 2 et 3"],["Arts plastiques","Créer un personnage, choisir des couleurs","Étape 2"]],
 remplace:"Une séance de calcul mental sur l’addition de plusieurs termes, et une séance de mesure. Les additions viennent des parties jouées : 10 + 2 + 1 + 1, on cherche à regrouper pour aller plus vite.",
 phase:"Réinvestissement du calcul et de la mesure",
 gain:["Les additions ont un enjeu, le score, et elles se répètent beaucoup.","Mesurer le tour d’une boîte, c’est mesurer une ligne courbe : un obstacle classique.","Le cylindre se déroule en rectangle sous les yeux.","Préparer la fête donne une responsabilité réelle à la classe."],
 concep:[["« On ne peut pas mesurer un rond avec une règle. »","La bande déroulée transforme le tour en segment que l’on mesure."],["« Pour additionner, on compte un par un. »","On regroupe : 5 + 5 = 10, puis on ajoute le reste."],["« L’habillage d’une boîte ronde est rond. »","On déroule l’étiquette d’une boîte : c’est un rectangle."]],
 relances:["Comment mesurer le tour avec ta règle ?","Quelle forme a l’étiquette quand on la déroule ?","Comment calculer plus vite 5 + 2 + 5 + 1 ?"],
 vocab:["tour","hauteur","rectangle","cylindre","addition","somme","score","pyramide"],
 trace:"<p>Pour mesurer le tour d’une boîte, je l’entoure d’une bande, puis je mesure la bande à plat.</p><p>L’habillage d’un cylindre est un rectangle.</p><p>Score : 10 + 2 + 1 + 1 = 14.</p>",
 aide:["Gabarit d’habillage fourni.","Points de 1 et 2 seulement."],
 expert:["Points de 10, 20, 50 et 100.","Trouver toutes les façons de faire 15 points."]},
"cocotte-langues":{
 notions:[["Langues vivantes","Poser et comprendre des questions simples ; se présenter","Étape 5 et séance 2"],["Mathématiques","Carré, diagonales, centre ; figures obtenues par pliage","Étapes 1 à 3"],["Enseignement moral et civique","Diversité des langues et des cultures de la classe","Collecte des questions avec les familles"],["Langage et français","Copier sans erreur, respecter l’orthographe d’une autre langue","Étape 4"]],
 remplace:"Une séance de langue vivante sur les questions de présentation, souvent faite en jeu de rôle. Les questions sont les mêmes, mais chaque élève fabrique son jeu et le pratique avec plusieurs camarades. En géométrie, une séance sur le carré et ses diagonales.",
 phase:"Entraînement oral en langue vivante",
 gain:["Les questions sont répétées naturellement, avec plusieurs camarades.","Les élèves qui le souhaitent partagent la langue parlée chez eux ; leur participation reste un choix.","Le pliage rend visibles les diagonales et le centre du carré.","Le jeu se réutilise toute l’année."],
 concep:[["« Le centre du carré, c’est à peu près au milieu. »","Avec les diagonales pliées, les coins tombent pile sur le centre."],["« On ne parle qu’une langue à l’école. »","Les langues de la classe entrent dans le jeu, chacun apprend un mot d’une autre langue."],["« Plier en deux, c’est toujours pareil. »","Selon une diagonale, on obtient un triangle ; selon le milieu des côtés, un rectangle."]],
 relances:["Comment trouver le centre sans règle ?","Quelle forme obtiens-tu après avoir rabattu les coins ?","Quelqu’un veut-il nous apprendre cette question dans une autre langue ?"],
 vocab:["carré","diagonale","centre","coin","pli","rabattre","question","réponse"],
 trace:"<p>Les diagonales d’un carré se coupent en son centre.</p><p>En rabattant les 4 coins sur le centre, on obtient un nouveau carré, plus petit.</p><p><b>Les questions de ma cocotte</b>, dans 3 langues.</p>",
 aide:["Carré déjà plié.","Questions à recopier."],
 expert:["Questions dans trois langues.","CM1 : expliquer pourquoi le petit carré a une aire deux fois plus petite."]},
"tissage":{
 notions:[["Mathématiques","Se repérer et coder sur un quadrillage : lignes, colonnes","Étape 3"],["Mathématiques","Reporter des longueurs égales avec la règle","Étape 1"],["Questionner le monde","Matériaux et objets : comment est fait un tissu (chaîne, trame)","Étapes 2 et 4"],["Arts plastiques","Motif, couleur, matière","Étapes 3 et 5"]],
 remplace:"Les séances de repérage sur quadrillage. Le tissage est un quadrillage en fils : chaque croisement de chaîne et de trame est une case du dessin.",
 phase:"Entraînement au repérage, puis production plastique",
 gain:["Le quadrillage devient matière : une erreur de rang se voit dans le tissu.","On comprend comment sont fabriqués les vêtements, observés à la loupe.","Patience et précision sont valorisées sur plusieurs séances.","Ouverture au cycle 3 : le métier Jacquard et ses cartes perforées."],
 concep:[["« Un tissu est fait d’une seule pièce. »","À la loupe, on voit sur un pull les fils qui se croisent, comme sur le métier."],["« Chaque rang se tisse pareil. »","Un rang dessus-dessous, le suivant dessous-dessus : sinon le fil ne tient pas."],["« Un quadrillage, c’est seulement sur papier. »","Une case du dessin correspond à un croisement de fils."]],
 relances:["Le rang d’avant commençait dessus ou dessous ?","Quelle case de ton dessin es-tu en train de tisser ?","Regarde ton pull à la loupe : que vois-tu ?"],
 vocab:["chaîne","trame","rang","croiser","dessus","dessous","motif","quadrillage","ligne","colonne"],
 trace:"<p>Un tissu est fait de fils qui se croisent : les fils de chaîne, tendus, et le fil de trame, qui passe dessus, dessous.</p><p>Chaque rang est l’inverse du précédent. <b>[mon motif sur quadrillage]</b></p>",
 aide:["Chaîne déjà montée.","Motif en bandes simples."],
 expert:["Damier ou lettre.","Métier plus fin : encoches tous les 5 mm."]},
"roue-emploi-du-temps":{
 notions:[["Mathématiques","Mesurer et construire un angle au rapporteur ; le tour complet vaut 360°","Étape 1"],["Mathématiques","Cercle, centre, rayon ; utiliser le compas","Étapes 1 et 3"],["Mathématiques","Division : 360 ÷ 5 = 72","Étape 1"],["Arts plastiques","Code couleur et lisibilité d’un document","Étape 2"]],
 remplace:"En 6e, la séance d’introduction au rapporteur. Au lieu de construire des angles isolés sur fiche, l’élève construit cinq angles de 72° qui doivent fermer le tour : une erreur se voit au dernier secteur.",
 phase:"Situation d’apprentissage en tout début d’année",
 gain:["Les erreurs s’additionnent et se voient dans le cinquième secteur : la précision devient nécessaire.","360° comme tour complet devient concret.","L’objet sert chaque jour, il est réutilisé.","Rentrée en 6e : l’élève s’approprie son emploi du temps."],
 concep:[["« Je lis le rapporteur sur n’importe quelle graduation. »","On obtient 108° au lieu de 72° : le secteur est visiblement trop grand."],["« Un angle dépend de la longueur de ses côtés. »","Sur le petit et le grand disque, le secteur garde le même angle."],["« Un tour, ça fait 100. »","Cinq parts de 72° font bien 360°."]],
 relances:["Sur quelle graduation lis-tu ? Celle qui part de 0 de ton côté ?","Combien de degrés pour faire le tour complet ?","Pourquoi le dernier secteur est-il plus grand ?"],
 vocab:["angle","degré","rapporteur","sommet","côté","secteur","rayon","centre","tour complet"],
 trace:"<p>Un tour complet mesure 360°. Pour partager un disque en 5 parts égales : 360 ÷ 5 = 72°.</p><p>Pour mesurer un angle, je place le centre du rapporteur sur le sommet et le 0 sur un des côtés.</p>",
 aide:["Disque pré-partagé, l’élève vérifie au rapporteur.","Gabarit d’angle de 72° en carton."],
 expert:["Roues à 6 et à 8 secteurs.","Calculer l’angle de la fenêtre pour ne voir qu’un jour."]},
"boite-messages":{
 notions:[["Enseignement moral et civique","Définir le harcèlement (répétition, rapport de force, isolement) ; rôle des témoins ; savoir à qui parler","Séance 1 et étape 5"],["Mathématiques","Patron du pavé droit ; rectangles et angles droits","Étapes 1 et 2"],["Sciences et technologie","Répondre à un cahier des charges ; une solution technique : la chicane","Étape 3 et test"],["Langage et français","Rédiger une règle d’usage claire","Étape 5"]],
 remplace:"La séance d’EMC de la journée contre le harcèlement, souvent menée à partir d’une vidéo et d’un débat. Le débat reste, mais il débouche sur un objet utile et une règle écrite par les élèves. En géométrie, la séance sur les patrons de pavés droits.",
 phase:"Débat d’EMC, puis réinvestissement en géométrie",
 gain:["Le débat a une suite concrète : la boîte montre que l’on peut en parler.","Les élèves écrivent eux-mêmes la règle d’usage et se l’approprient.","Le patron aux dimensions imposées est une vraie tâche de géométrie.","La chicane répond à un problème réel : protéger la confidentialité."],
 concep:[["« Le harcèlement, c’est quand on se bat. »","On distingue la dispute ponctuelle du harcèlement : répétition, rapport de force, isolement."],["« En parler, c’est cafter. »","Demander de l’aide protège la victime ; le témoin a un rôle décisif."],["« Six rectangles font toujours une boîte. »","Si les faces opposées ne sont pas identiques, la boîte ne ferme pas."]],
 relances:["Quelle différence entre une dispute et du harcèlement ?","À qui peut-on parler dans l’école ?","Quelles arêtes vont se coller ensemble ?","Comment empêcher qu’on reprenne un message ?"],
 vocab:["harcèlement","répétition","témoin","confiance","patron","pavé droit","face","arête","chicane"],
 trace:"<p>Le harcèlement, ce sont des violences répétées contre une même personne, qui se retrouve isolée. Si je suis victime ou témoin, j’en parle à un adulte de confiance.</p><p>Un pavé droit a 6 faces rectangulaires ; les faces opposées sont identiques.</p>",
 aide:["Patron pré-tracé à découper.","Cube de 10 cm à la place du pavé."],
 expert:["Calculer le volume.","Dessiner la chicane avec un schéma coté."]},
"pochette-cousue":{
 notions:[["Sciences et technologie","Assemblages ; choisir une solution par un test ; ne changer qu’une variable","Étape 3 et test"],["Mathématiques","Mesurer et tracer des longueurs ; masses en kg et g","Étapes 3 et 4"],["Arts plastiques","Broderie, décor, initiale","Étape 6"]],
 remplace:"En sciences et technologie, la séance sur les assemblages, souvent menée sur documents. Ici, les élèves testent eux-mêmes la solidité de plusieurs coutures avant de choisir. En mathématiques, une séance de mesure et de construction de rectangles.",
 phase:"Investigation, puis fabrication",
 gain:["Le test transforme un geste artisanal en expérience : une variable, des mesures, une conclusion.","Le choix du point est justifié par des preuves.","Geste précis et patience sont valorisés.","L’objet est utile ou offert : le soin a un sens."],
 concep:[["« Plus il y a de points, plus c’est solide, toujours. »","Des points trop serrés peuvent déchirer la feutrine : le test le montre."],["« La couture tient grâce au fil seulement. »","On observe où ça lâche : le fil, le nœud ou le tissu."],["« Coudre, ce n’est pas pour tout le monde. »","Tous les élèves cousent ; on cite des métiers : tailleur, chirurgien, voilier, sellier."]],
 relances:["Où ta couture a-t-elle lâché ?","Qu’as-tu changé d’une éprouvette à l’autre ?","Quel point choisis-tu, et pourquoi ?"],
 vocab:["aiguille","chas","fil","nœud d’arrêt","point avant","surjet","marge","éprouvette","assemblage"],
 trace:"<p>Pour assembler deux pièces de tissu, on peut coudre au point avant ou au point de surjet.</p><p>Notre test : le surjet de 5 mm a tenu 2,5 kg, le point avant de 1 cm seulement 1 kg. Nous choisissons le surjet.</p>",
 aide:["Repères de couture tracés à la craie.","Enfile-aiguille."],
 expert:["Point arrière.","Trousse avec soufflet."]},
"roue-kermesse":{
 notions:[["Mathématiques","Probabilité d’un événement dans une situation d’équiprobabilité","Étape 1"],["Mathématiques","Fréquence et probabilité ; stabilisation des fréquences","Étape 5"],["Mathématiques","Angles, rapporteur ; proportionnalité pour prévoir les lots","Étapes 2 et 5"],["Sciences et technologie","Liaison pivot, frottement, équilibrage","Étapes 3 et 4"]],
 remplace:"La séance d’introduction aux probabilités en 4e, ou celle sur fréquence et probabilité en 3e, souvent menée avec des pièces et des dés. Ici, les élèves conçoivent l’expérience aléatoire et découvrent qu’une roue mal fabriquée n’est pas équiprobable.",
 phase:"Situation-problème, puis expérimentation",
 gain:["Concevoir l’expérience oblige à comprendre ce que veut dire « équiprobable ».","La roue déséquilibrée montre la différence entre le modèle et l’objet réel.","Avec 100 lancers par groupe et le cumul de la classe, on voit les fréquences se stabiliser.","Le calcul sert : on prévoit le nombre de lots pour la fête."],
 concep:[["« 3 secteurs gagnants sur 12, c’est 3 chances sur 9. »","On compte toutes les issues : 12 secteurs, dont 3 gagnants, 3/12 = 1/4."],["« Si je n’ai pas gagné depuis longtemps, je vais gagner. »","Chaque lancer est indépendant : les séries de perdants apparaissent dans le tableau."],["« 100 lancers donnent exactement 25 lots. »","Les groupes trouvent 22, 27, 31… La fréquence se rapproche de 0,25 quand on cumule."]],
 relances:["Combien d’issues ? Sont-elles toutes aussi probables ?","Votre roue est-elle équitable ? Comment le prouver ?","Combien de lots prévoir pour 300 joueurs ?"],
 vocab:["issue","événement","équiprobable","probabilité","fréquence","effectif","secteur","liaison pivot","équilibrage"],
 trace:"<p>Quand toutes les issues ont la même probabilité : probabilité d’un événement = nombre d’issues favorables ÷ nombre total d’issues.</p><p>Roue de 12 secteurs égaux dont 3 gagnants : P = 3/12 = 1/4.</p><p>Quand le nombre de lancers augmente, la fréquence se rapproche de la probabilité.</p>",
 aide:["Roue pré-tracée en 12 secteurs.","Tableau des fréquences préparé."],
 expert:["Roue à secteurs inégaux : probabilité par les angles.","Simulation de 10 000 lancers sur tableur ou avec Scratch."]},
"sac-tshirt":{
 notions:[["Sciences et technologie","Cycle de vie d’un objet, matériaux, impact environnemental ; réemploi et recyclage","Séance 1"],["Sciences et technologie","Comparer deux solutions d’assemblage selon des critères ; test de charge","Étapes 2 à 4"],["Mathématiques","Proportionnalité, conversions de masses et de durées","Séance 3 : 300 sacs"],["Arts plastiques","Personnalisation, pochoir, message","Étape 5"]],
 remplace:"La séance de technologie sur le cycle de vie et l’impact environnemental d’un objet, souvent menée sur documents. Le t-shirt est un objet que chaque élève connaît, et le réemploi est vécu.",
 phase:"Analyse, puis conception et test",
 gain:["Le cycle de vie s’applique à un objet que l’on tient dans les mains.","La comparaison est multicritère : solidité, temps, outils, aspect.","Le choix pour 300 sacs fait raisonner comme en production.","Le geste de réemploi est concret et utile."],
 concep:[["« Recycler, c’est jeter dans la bonne poubelle. »","On distingue réemploi, réparation et recyclage : ici, le t-shirt garde sa matière."],["« Un t-shirt est trop fragile pour porter du poids. »","Le test de charge montre que le sac porte 5 kg."],["« La machine, c’est toujours mieux. »","Le noué est plus rapide sans machine, le cousu plus net : tout dépend des critères."]],
 relances:["Par où ton t-shirt est-il passé avant d’arriver chez toi ?","Quelle méthode pour 300 sacs ? Pourquoi ?","Comment mesurer que le sac a résisté ?"],
 vocab:["cycle de vie","matière première","réemploi","recyclage","impact","assemblage","critère","test de charge"],
 trace:"<p>Le cycle de vie d’un objet : matières premières, fabrication, transport, utilisation, fin de vie.</p><p>Réemployer un t-shirt évite de fabriquer un sac neuf.</p><p>Notre test : le sac noué et le sac cousu portent 5 kg ; le cousu s’allonge moins.</p>",
 aide:["Gabarit de découpe.","Une seule méthode."],
 expert:["Plan de fabrication en série.","Calculer la masse de textile réemployée par la classe."]},
"pochoir-campagne":{
 notions:[["Enseignement moral et civique","Harcèlement et cyberharcèlement ; rôle des témoins ; s’engager","Séance 1"],["Arts plastiques","Image de communication : message court, contraste, pictogramme ; reproduction en série","Étapes 1, 2 et 5"],["Mathématiques","Agrandissement : coefficient 2 du format A5 au format A3","Étape 3"],["Sciences et technologie","Contraintes de fabrication (îlots, ponts) ; production en série, temps par pièce","Étapes 4 et 5"]],
 remplace:"La séance d’EMC de la journée contre le harcèlement, et en arts plastiques la séquence sur l’image de communication. Le débat débouche sur une campagne réelle, conçue et imprimée par les élèves pour leur collège.",
 phase:"Projet de communication qui réinvestit l’EMC",
 gain:["Le message vise une vraie cible, les témoins : il est retravaillé jusqu’à être efficace.","La contrainte du pochoir oblige à simplifier, ce qui rend le message plus fort.","La série chronométrée introduit l’organisation d’une production.","Les élèves deviennent acteurs de la prévention dans leur établissement."],
 concep:[["« Une affiche efficace explique tout. »","À 5 m, on lit 5 mots : le test de lecture le montre."],["« Le harcèlement ne concerne que la victime et l’agresseur. »","Les témoins peuvent l’arrêter en en parlant : la campagne s’adresse à eux."],["« Un pochoir reproduit n’importe quel dessin. »","Les zones fermées tombent : il faut des ponts."]],
 relances:["À qui s’adresse ton affiche ? Que doit-il faire ensuite ?","Que restera-t-il de la lettre A après la découpe ?","Comment imprimer 20 affiches plus vite ?"],
 vocab:["slogan","pictogramme","pochoir","pont","îlot","contraste","série","témoin","cyberharcèlement"],
 trace:"<p>Le harcèlement est une violence répétée qui isole une personne. Les témoins peuvent l’arrêter en en parlant à un adulte.</p><p>Une image de communication transmet un message court, lisible et ciblé.</p><p>Un pochoir permet de reproduire une image en série ; les zones fermées ont besoin de ponts.</p>",
 aide:["Police de caractères pochoir fournie.","Pictogramme simple proposé."],
 expert:["Pochoir en deux couleurs avec calage.","Calculer le temps nécessaire pour 200 affiches."]}
});

