const addSrc=(id,arr)=>{const p=P.find(x=>x.id===id);if(p)p.source=(p.source||[]).concat(arr)};
addSrc("pont-papier",[SRC.ponts]);addSrc("bateau-alu",[SRC.flotte]);addSrc("tour-papier",[SRC.pierres]);addSrc("pochette-cousue",[SRC.pochette]);addSrc("sac-tshirt",[SRC.soleil]);addSrc("mobile",[SRC.air]);
/* helpers */
const bottle=(cx,top,w,h)=>`<rect class="tpf" x="${cx-9}" y="${top}" width="18" height="12" rx="2"/><path class="bot" d="M${cx-8} ${top+12} L${cx-8} ${top+20} Q${cx-w/2} ${top+26} ${cx-w/2} ${top+42} L${cx-w/2} ${top+h} Q${cx} ${top+h+6} ${cx+w/2} ${top+h} L${cx+w/2} ${top+42} Q${cx+w/2} ${top+26} ${cx+8} ${top+20} L${cx+8} ${top+12} Z"/>`;
const seeds=(x1,x2,y1,y2,n=26)=>{let o="";for(let i=0;i<n;i++){const x=x1+((i*37)%100)/100*(x2-x1),y=y1+((i*53)%100)/100*(y2-y1);o+=`<circle class="seed" cx="${f1(x)}" cy="${f1(y)}" r="2.2"/>`}return o};
function house(x,y,w,h,k){const c=k==="p"?"tpf":k==="b"?"k":"of";let o=`<polygon class="${k==="r"?"vr":c}" points="${x-6},${y} ${x+w/2},${f1(y-h*.6)} ${x+w+6},${y}"/><rect class="${c}" x="${x}" y="${y}" width="${w}" height="${h}"/>`;
 if(k==="p")for(let i=4;i<w;i+=5)o+=`<line class="o" style="stroke-width:1;opacity:.6" x1="${x+i}" y1="${y+2}" x2="${x+i}" y2="${y+h-2}"/>`;
 if(k==="b")for(let j=8;j<h;j+=8)o+=`<line class="o" style="stroke-width:1;opacity:.6" x1="${x}" y1="${y+j}" x2="${x+w}" y2="${y+j}"/>`;
 if(k==="r")for(let j=0;j*8<h;j++)for(let i=-(j%2)*7;i<w;i+=14)o+=`<rect class="vr" style="stroke-width:.8" x="${Math.max(x,x+i)}" y="${y+j*8}" width="${Math.min(14,x+w-Math.max(x,x+i))-0}" height="8"/>`;
 return o+`<rect class="ink" x="${x+w/2-6}" y="${y+h-16}" width="12" height="16"/>`}
const cupDose=(x,y,c)=>`<path class="${c}" d="M${x} ${y} L${x+22} ${y} L${x+18} ${y+28} L${x+4} ${y+28} Z"/>`;
function brickWall(x,y,cols,rows,bw,bh,stag){let o="";for(let r=0;r<rows;r++){const off=stag&&(r%2)?-bw/2:0;for(let c=0;c<=cols;c++){const bx=x+c*bw+off;const x1=Math.max(x,bx),x2=Math.min(x+cols*bw,bx+bw);if(x2-x1>2)o+=`<rect class="k" x="${x1}" y="${y-(r+1)*bh}" width="${x2-x1}" height="${bh}" style="stroke-width:1.2"/>`}}return o}
const kid=(x,base,h)=>`<circle class="of" cx="${x}" cy="${base-h+10}" r="10"/><path class="lf" d="M${x-12} ${base} L${x-10} ${base-h+22} Q${x} ${base-h+18} ${x+10} ${base-h+22} L${x+12} ${base} Z"/>`;
const jar=(x,base,w,h,lv)=>`<rect class="w" x="${x}" y="${base-lv}" width="${w}" height="${lv}"/><path class="o" d="M${x} ${base-h} L${x} ${base} L${x+w} ${base} L${x+w} ${base-h}"/>`;
const sprout=(x,base,h)=>`<path class="o" style="stroke:var(--leaf-dk);stroke-width:2.5" d="M${x} ${base} Q${x-3} ${base-h/2} ${x} ${base-h}"/><ellipse class="lf" cx="${x-6}" cy="${base-h}" rx="6" ry="3" transform="rotate(-25 ${x-6} ${base-h})"/><ellipse class="lf" cx="${x+6}" cy="${base-h}" rx="6" ry="3" transform="rotate(25 ${x+6} ${base-h})"/>`;
function sprayHand(cx,cy){let o="";for(let i=0;i<70;i++){const a=i*2.4,r=44+((i*29)%18);o+=`<circle class="ocre" cx="${f1(cx+r*Math.cos(a))}" cy="${f1(cy+r*Math.sin(a)*1.05)}" r="${2+(i%3)}"/>`}return o+`<g transform="translate(${cx-27} ${cy-38}) scale(.9)"><path class="kd" d="${HAND}" style="stroke:var(--ink);stroke-width:1;stroke-dasharray:3 3;opacity:.8"/></g>`}
const ice=(x,y,s)=>`<rect class="ice" x="${x}" y="${y}" width="${s}" height="${s}" rx="3"/><line class="o" style="stroke-width:1;opacity:.5" x1="${x+4}" y1="${y+4}" x2="${x+s*.5}" y2="${y+4}"/>`;
const scale=(cx,y,txt)=>`<rect class="of" x="${cx-50}" y="${y}" width="100" height="40" rx="6"/><rect class="ink" x="${cx-26}" y="${y+12}" width="52" height="18" rx="3"/><text x="${cx}" y="${y+26}" text-anchor="middle" style="font-family:var(--f-mono);font-size:13px;fill:var(--glow)">${txt}</text><rect class="of" x="${cx-36}" y="${y-6}" width="72" height="6" rx="2"/>`;
const swatch=(x,y,s,k)=>{const base=`<rect class="${k==="noir"?"ink":k==="jean"?"cv":k==="voile"?"of":k==="polaire"?"pk":"tpf"}" x="${x}" y="${y}" width="${s}" height="${s}"${k==="voile"?' style="opacity:.5"':""}/>`;let pat="";if(k==="jean")for(let i=4;i<s;i+=6)pat+=`<line class="o" style="stroke-width:.8;opacity:.5" x1="${x+i}" y1="${y}" x2="${x}" y2="${y+i}"/>`;if(k==="voile")pat=`<rect class="o dash" x="${x}" y="${y}" width="${s}" height="${s}"/>`;if(k==="polaire")for(let i=0;i<6;i++)pat+=`<circle class="of" style="stroke-width:.6" cx="${x+6+(i%3)*((s-12)/2)}" cy="${y+8+Math.floor(i/3)*(s-16)}" r="3"/>`;return base+pat};
const sun=(cx,cy,r)=>`<circle class="tpf" cx="${cx}" cy="${cy}" r="${r}"/>`+Array.from({length:8},(_,i)=>{const a=i*Math.PI/4,p=pol(cx,cy,r+4,a*180/Math.PI),q=pol(cx,cy,r+12,a*180/Math.PI);return `<line class="o" style="stroke:var(--tape);stroke-width:3" x1="${f1(p[0])}" y1="${f1(p[1])}" x2="${f1(q[0])}" y2="${f1(q[1])}"/>`}).join("");
const heli=(x,top,bl,sc=1)=>`<g transform="translate(${x} ${top}) scale(${sc})"><polygon class="tpf" points="0,${bl} -${bl*1.6},${bl*.55} -${bl*1.6},${bl*.55+8} 0,${bl+8}"/><polygon class="pk" points="10,${bl} ${10+bl*1.6},${bl*.55} ${10+bl*1.6},${bl*.55+8} 10,${bl+8}"/><rect class="of" x="0" y="${bl}" width="10" height="44"/><rect class="ink" x="2" y="${bl+40}" width="6" height="10" rx="2"/></g>`;

