 concep:[["« La paille, c’est toujours fragile. »","La paille serrée en bottes tient mieux que des brins posés : la construction compte."],["« Plus c’est lourd, mieux c’est. »","Des briques en colonnes tombent ; décalées, elles tiennent."],["« Souffler, c’est toujours pareil. »","On range les souffles : bouche, éventail, sèche-cheveux."]],
 relances:["Pourquoi ta maison est-elle tombée ?","Comment être sûr que le loup souffle pareil sur toutes les maisons ?","Que changerais-tu pour qu’elle tienne ?"],
