 concep:[["« Quand il y a des nuages, on ne risque rien. »","Si l’on refait le test par temps voilé, le papier change aussi : les UV passent."],["« Tous les tissus protègent pareil. »","Le voile laisse passer beaucoup d’UV, le jean presque pas."],["« Le soleil brûle seulement quand il fait chaud. »","Les UV ne se sentent pas ; la chaleur, si."]],
 relances:["Pourquoi garder une fenêtre sans tissu ?","Qu’est-ce qui fait qu’un tissu protège mieux : la couleur, l’épaisseur, le tissage ?","Comment te protéger pendant une sortie ?"],
 vocab:["UV","rayonnement","protéger","épais","fin","tissage","témoin","visière"],
