const gear4=(cx,cy,r,n,c="k")=>{const pts=[],s=2*Math.PI/n,ri=r-6;for(let i=0;i<n;i++){const a=s*i;[[ri,a],[r,a+s*.2],[r,a+s*.5],[ri,a+s*.7]].forEach(([rr,aa])=>pts.push(f1(cx+rr*Math.cos(aa))+","+f1(cy+rr*Math.sin(aa))))}return `<polygon class="${c}" points="${pts.join(" ")}"/><circle class="of" cx="${cx}" cy="${cy}" r="3.5"/>`};
const rot4=(cx,cy,r,a1,a2)=>{const p=pol(cx,cy,r,a1),q=pol(cx,cy,r,a2),qb=pol(cx,cy,r,a2-(a2>a1?10:-10));return `<path class="a" d="M${f1(p[0])} ${f1(p[1])} A${r} ${r} 0 0 ${a2>a1?1:0} ${f1(q[0])} ${f1(q[1])}"/>`+arr(+f1(qb[0]),+f1(qb[1]),+f1(q[0]),+f1(q[1]))};
const pileS=(x,y)=>`<rect x="${x-3}" y="${y-12}" width="13" height="24" style="fill:var(--card)"/><line class="o" x1="${x}" y1="${y-11}" x2="${x}" y2="${y+11}"/><line class="o" style="stroke-width:4" x1="${x+7}" y1="${y-6}" x2="${x+7}" y2="${y+6}"/>`+L(x-6,y-12,"+","t","middle");
const lampS=(x,y,on)=>`${on?`<circle class="gl" cx="${x}" cy="${y}" r="15"/>`:""}<circle class="of" cx="${x}" cy="${y}" r="8"/><line class="o" style="stroke-width:1.5" x1="${x-5.6}" y1="${y-5.6}" x2="${x+5.6}" y2="${y+5.6}"/><line class="o" style="stroke-width:1.5" x1="${x-5.6}" y1="${y+5.6}" x2="${x+5.6}" y2="${y-5.6}"/>`;
const swS=(x,y,closed)=>`<rect x="${x-2}" y="${y-14}" width="26" height="18" style="fill:var(--card)"/><circle class="ink" cx="${x}" cy="${y}" r="2.5"/><circle class="ink" cx="${x+22}" cy="${y}" r="2.5"/><line class="o" x1="${x}" y1="${y}" x2="${closed?x+22:x+19}" y2="${closed?y:y-11}"/>`;
const torch4=(x,y)=>`<rect class="af" x="${x}" y="${y-7}" width="30" height="14" rx="3"/><path class="tpf" d="M${x+30} ${y-7} L${x+40} ${y-11} L${x+40} ${y+11} L${x+30} ${y+7} Z"/>`;
const phone4=(x,y,txt)=>`<rect class="ink" x="${x}" y="${y}" width="24" height="42" rx="4"/><rect class="of" x="${x+3}" y="${y+6}" width="18" height="28" rx="1"/>${txt?`<text x="${x+12}" y="${y+24}" text-anchor="middle" style="font-family:var(--f-mono);font-size:8px;fill:var(--ink)">${txt}</text>`:""}`;
const cup4=(x,y)=>`<path class="of" d="M${x-14} ${y} L${x+14} ${y} L${x+10} ${y+20} L${x-10} ${y+20} Z"/>`;
function beam4(cx,cy,half,tilt,hang){const a=tilt*Math.PI/180,dx=half*Math.cos(a),dy=half*Math.sin(a);const lx=cx-dx,ly=cy-dy,rx=cx+dx,ry=cy+dy;
 return `<line class="o" style="stroke:var(--kraft-dk);stroke-width:7" x1="${f1(lx)}" y1="${f1(ly)}" x2="${f1(rx)}" y2="${f1(ry)}"/><circle class="ink" cx="${cx}" cy="${cy-2}" r="2.5"/>`+[[lx,ly],[rx,ry]].map(([x,y])=>`<line class="o" style="stroke-width:1.2" x1="${f1(x)}" y1="${f1(y)}" x2="${f1(x-12)}" y2="${f1(y+hang)}"/><line class="o" style="stroke-width:1.2" x1="${f1(x)}" y1="${f1(y)}" x2="${f1(x+12)}" y2="${f1(y+hang)}"/>`+cup4(+f1(x),+f1(y+hang))).join("")}
const stand4=(cx,top,base)=>`<path class="k" d="M${cx-8} ${base} L${cx-3} ${top} L${cx+3} ${top} L${cx+8} ${base} Z"/><rect class="kd" x="${cx-36}" y="${base}" width="72" height="8" rx="2"/>`;
const wheel4=(cx,cy,r)=>`<circle class="of" cx="${cx}" cy="${cy}" r="${r}"/><circle class="ink" cx="${cx}" cy="${cy}" r="2"/>`;
const grid4=(x,y,n,s)=>{let o=`<rect class="of" x="${x}" y="${y}" width="${n*s}" height="${n*s}"/>`;for(let i=1;i<n;i++)o+=`<line class="gridl" style="stroke:var(--muted);opacity:.6" x1="${x+i*s}" y1="${y}" x2="${x+i*s}" y2="${y+n*s}"/><line class="gridl" style="stroke:var(--muted);opacity:.6" x1="${x}" y1="${y+i*s}" x2="${x+n*s}" y2="${y+i*s}"/>`;return o};
const lutin4=(cx,cy,dir)=>{const r={n:0,e:90,s:180,w:270}[dir];return `<g transform="rotate(${r} ${cx} ${cy})"><circle class="af" cx="${cx}" cy="${cy}" r="7"/><path class="tpf" d="M${cx-4} ${cy-5} L${cx} ${cy-12} L${cx+4} ${cy-5} Z"/></g>`};
const chest4=(x,y)=>`<rect class="tpf" x="${x-8}" y="${y-5}" width="16" height="11" rx="2"/><line class="o" style="stroke-width:1.2" x1="${x-8}" y1="${y}" x2="${x+8}" y2="${y}"/>`;
const card4=(x,y,k,bad)=>{const w=24,h=28;let ic="";const cx=x+w/2,cy=y+h/2;
 if(k==="F")ic=`<path class="a" d="M${cx} ${cy+8} L${cx} ${cy-6}"/>`+arr(cx,cy-2,cx,cy-9);
 if(k==="G")ic=`<path class="a" d="M${cx+5} ${cy+8} L${cx+5} ${cy} Q${cx+5} ${cy-5} ${cx} ${cy-5} L${cx-4} ${cy-5}"/>`+arr(cx-1,cy-5,cx-8,cy-5);
 if(k==="D")ic=`<path class="a" d="M${cx-5} ${cy+8} L${cx-5} ${cy} Q${cx-5} ${cy-5} ${cx} ${cy-5} L${cx+4} ${cy-5}"/>`+arr(cx+1,cy-5,cx+8,cy-5);
 return `<rect class="${bad?"vr":"of"}" x="${x}" y="${y}" width="${w}" height="${h}" rx="3"${bad?' style="fill-opacity:.25"':""}/>`+ic};
const room4=(x,y,w,h)=>`<rect class="of" x="${x}" y="${y}" width="${w}" height="${h}"/>`;

