Object.assign(D,{
"voiture-roule":{
 notions:[["Questionner le monde","Objet technique : fonction, cahier des charges","Séance 1"],["Questionner le monde","Fonctionnement : roue, axe, support, frottement","Étapes 1 à 3"],["Mathématiques","Mesurer des longueurs en cm et en m ; comparer des mesures","Étape 5"],["Mathématiques","Angle droit : tracer avec un gabarit","Étape 2"],["Langage et français","Dire ce que l’on a changé et pourquoi","Séance 3"]],
 remplace:"La séance sur les objets techniques à partir d’images ou d’un objet démonté. Ici, les élèves construisent l’objet et découvrent la fonction de chaque pièce en résolvant ses défauts.",
 phase:"Conception et amélioration d’un objet",
 gain:["Chaque défaut a une cause que l’élève peut voir et corriger.","La mesure départage les voitures sans discussion.","Le vocabulaire technique naît de l’objet : axe, support, frotter.","Changer une seule chose à la fois devient une habitude."],
 concep:[["« Pour que les roues tiennent, on les colle au châssis. »","Collées, elles ne tournent plus : la roue a besoin d’un axe qui tourne."],["« Elle va de travers parce qu’on l’a mal lâchée. »","Si elle tourne toujours du même côté, ce sont les axes qui ne sont pas parallèles."],["« Plus elle est lourde, moins elle va loin. »","On ajoute de la pâte à fixe et on mesure avant de conclure."]],
 relances:["Qu’est-ce qui tourne sur ta voiture ?","Pourquoi tourne-t-elle toujours du même côté ?","Qu’as-tu changé entre les deux essais ?"],
 vocab:["roue","axe","support","châssis","tourner","frotter","parallèle","pente","distance"],
 trace:"<p><b>Dessin légendé de la voiture.</b></p><p>Pour qu’une voiture roule, les roues tournent avec un axe qui tourne dans un support sans frotter. Pour qu’elle roule droit, les deux axes doivent être parallèles. Ma voiture a roulé 1 m 40.</p>",
 aide:["Châssis avec les traits déjà tracés.","Mesurer seulement la distance, pas l’écart."],
 expert:["Améliorer la voiture pour qu’elle dépasse 2 m.","Comparer deux tailles de roues."]},
"balance-classe":{
 notions:[["Mathématiques","Comparer et ranger des masses ; la taille ne dit pas la masse","Étape 4"],["Mathématiques","Mesurer une masse en grammes avec des masses marquées","Étape 5"],["Questionner le monde","Un instrument de mesure : fabriquer, régler, vérifier","Étapes 1 à 3"],["Langage et français","Plus lourd que, aussi lourd que, le plus léger","Étape 4"]],
 remplace:"La séance de grandeurs et mesures sur les masses, souvent faite avec la balance de la classe ou sur fiche. Ici, l’élève comprend l’instrument parce qu’il l’a construit et réglé.",
 phase:"Découverte d’une grandeur, puis mesure",
 gain:["L’élève voit pourquoi la balance « marche » : il a placé l’axe et réglé le fléau.","Comparer avant de mesurer installe le sens de la grandeur.","Fabriquer les masses de 5, 10, 20 et 50 g donne du sens au gramme.","L’écart avec la balance de cuisine ouvre la question de la précision."],
 concep:[["« Le plus gros est le plus lourd. »","La grosse boule de papier monte, la petite bille descend."],["« Une balance est en équilibre seulement quand elle est horizontale. »","Le fléau s’arrête aussi penché : on dit « le fléau est horizontal » quand les masses sont égales."],["« Peser, c’est lire un nombre sur un écran. »","Sur notre balance, on compare à des masses connues : c’est le principe de la mesure."]],
 relances:["Comment être sûr que ta balance est juste ?","Pourquoi le gobelet descend-il ?","Avec quels sachets peut-on faire 35 g ?"],
 vocab:["masse","plus lourd","plus léger","fléau","plateau","horizontal","gramme","masse marquée"],
 trace:"<p><b>Photo de la balance et tableau des mesures.</b></p><p>Pour comparer deux masses, on utilise une balance : le plateau qui descend porte l’objet le plus lourd. Quand le fléau est horizontal, les deux plateaux portent la même masse. Ma gomme a une masse de 25 g.</p>",
 aide:["Balance déjà montée : l’élève règle et compare.","Comparer seulement, sans mesurer en grammes."],
 expert:["Peser avec le moins de sachets possible.","Mesurer la sensibilité de sa balance en trombones."]},
"robot-programme":{
 notions:[["Se repérer dans l’espace","Se déplacer sur un quadrillage ; gauche, droite, devant, derrière","Étapes 1 et 2"],["Mathématiques","Coder et décoder un déplacement ; compter des cases","Étapes 3 et 4"],["Mathématiques","Comparer deux programmes : lequel est le plus court ?","Séance 4"],["Langage et français","Formuler un ordre précis","Étape 1"]],
 remplace:"La séance de repérage dans l’espace sur fiche, avec des flèches à suivre sur un quadrillage. Ici, l’élève écrit lui-même le chemin, et un autre groupe vérifie qu’il est juste.",
 phase:"Situation de communication : écrire pour un autre",
 gain:["Le corps d’abord : jouer le robot rend les instructions concrètes.","Écrire le programme avant d’agir oblige à anticiper.","L’erreur devient un objet de travail : on cherche la carte fausse.","Le jeu de cartes resservira avec un robot de sol."],
 concep:[["« Le robot sait où il doit aller. »","Il ne fait que ce que disent les cartes : s’il se trompe, c’est le programme."],["« Tourner, c’est aller sur la case d’à côté. »","Tourner se fait sur place : le lutin change seulement de direction."],["« La gauche, c’est toujours le même côté de la feuille. »","Quand le lutin nous fait face, sa gauche est à notre droite : on se met à sa place."]],
 relances:["De combien de cases doit-il avancer ?","Vers où regarde le lutin maintenant ?","À quelle carte s’est-il trompé ?"],
 vocab:["instruction","programme","avancer","tourner","gauche","droite","case","quart de tour","erreur"],
 trace:"<p><b>Photo du programme et du plateau.</b></p><p>Un programme est une suite d’instructions. Le lutin fait exactement ce que disent les cartes, dans l’ordre. Quand il n’arrive pas au trésor, on cherche la carte fausse et on la change.</p>",
 aide:["Plateau de 3 × 3 cases, sans obstacle.","Seulement la carte « avancer » et des flèches de direction."],
 expert:["Le programme le plus court.","Utiliser une carte « répéter »."]},
"manege-engrenages":{
 notions:[["Sciences et technologie","Transmettre une rotation : poulies, courroie, engrenages","Étapes 1, 3 et 4"],["Sciences et technologie","Le sens de rotation : engrenages en contact, courroie croisée","Étape 5"],["Mathématiques","Comparer des diamètres, compter des dents, relation « 3 pour 1 »","Étape 2"],["Mathématiques","Prévoir puis mesurer ; expliquer un écart","Test"]],
 remplace:"La séance sur le fonctionnement d’un objet technique, souvent faite à partir d’un schéma ou d’une vidéo. Ici, les élèves construisent la transmission et vérifient ce qu’ils ont prévu.",
 phase:"Investigation, puis conception",
 gain:["La dent marquée rend visibles le nombre de tours et le sens.","Le calcul « 36, c’est 3 fois 12 » se vérifie sur l’objet.","L’écart dû au glissement de la courroie ouvre une vraie discussion.","Le projet prépare l’automate à came du cycle 4."],
 concep:[["« La grande roue tourne plus vite parce qu’elle est plus grande. »","On compte les tours : c’est la petite qui en fait le plus."],["« Toutes les roues tournent dans le même sens. »","Deux engrenages en contact tournent en sens contraire : la dent marquée le montre."],["« Si la mesure ne colle pas avec le calcul, je me suis trompé. »","La courroie glisse : l’écart a une cause que l’on peut chercher."]],
 relances:["Combien de tours fait la petite roue quand la grande en fait un ?","Dans quel sens tourne la troisième roue ?","Pourquoi as-tu compté moins de 3 tours ?"],
 vocab:["axe","poulie","courroie","engrenage","dent","roue menante","roue menée","sens de rotation","transmettre"],
 trace:"<p><b>Schéma du manège avec les flèches de sens.</b></p><p>La poulie de la manivelle entraîne la poulie du manège grâce à une courroie. La poulie du manège est trois fois plus grande : il faut 3 tours de manivelle pour 1 tour de manège. Deux engrenages en contact tournent en sens contraire.</p>",
 aide:["Socle déjà percé, axes en place.","Travailler seulement avec les poulies."],
 expert:["Faire tourner le manège deux fois plus vite que la manivelle.","Prévoir le résultat d’un train de trois engrenages."]},
"brassard-nuit":{
 notions:[["Sciences et technologie","Voir un objet : la lumière qu’il renvoie doit entrer dans l’œil","Étape 1"],["Sciences et technologie","Diffuser, absorber, renvoyer vers la source","Étapes 2 et 3"],["Physique-chimie","Sources de lumière et objets diffusants ; mesurer un éclairement en lux","Étapes 2 et 3"],["Mathématiques","Répéter une mesure, ranger des résultats","Étape 3"]],
 remplace:"La séance sur la lumière et la vision, souvent faite à partir de schémas. Ici, la question de sécurité routière donne un enjeu, et la mesure tranche entre les hypothèses.",
 phase:"Démarche expérimentale, puis fabrication",
 gain:["L’expérience du noir complet règle la question « on voit parce qu’on regarde ».","Le luxmètre remplace « je trouve que » par une mesure.","La place du capteur, près de la lampe, fait comprendre la rétroréflexion.","Le brassard sert pour les sorties scolaires."],
 concep:[["« On voit parce qu’on regarde. »","Dans le noir complet, on ne voit rien : il faut que de la lumière arrive dans l’œil."],["« La bande réfléchissante brille toute seule. »","Lampe éteinte, elle est invisible : ce n’est pas une source de lumière."],["« Le blanc, c’est ce qui se voit le mieux. »","Avec le capteur près de la lampe, on compare la bande et le blanc par la mesure."]],
 relances:["La bande est-elle une source de lumière ?","Pourquoi le téléphone doit-il être à côté de la lampe ?","Où se trouvent les yeux du conducteur par rapport à ses phares ?"],
 vocab:["source de lumière","éclairer","diffuser","absorber","renvoyer","rétroréfléchissant","luxmètre","lux"],
 trace:"<p><b>Tableau des mesures de la classe.</b></p><p>Un objet n’est visible que s’il est éclairé et s’il renvoie de la lumière vers nos yeux. Le tissu noir absorbe presque toute la lumière. Le tissu blanc la diffuse dans toutes les directions. La bande rétroréfléchissante la renvoie surtout vers la lampe : le conducteur, placé juste derrière ses phares, la voit très bien.</p>",
 aide:["Trois échantillons seulement : noir, blanc, bande.","Tableau de mesures pré-rempli pour les échantillons."],
 expert:["Mesurer avec le capteur à 50 cm de la lampe, puis comparer.","Tester un gilet du commerce et expliquer le résultat."]},
"stenope":{
 notions:[["Sciences et technologie","La lumière se propage en ligne droite ; l’image est renversée","Étapes 3 et 4"],["Sciences et technologie","Démarche expérimentale : une seule variable, le trou","Étape 5"],["Arts plastiques","L’image, le cadrage, un dispositif pour voir","Étape 3"],["Mathématiques","Mesurer la hauteur de l’image, comparer","Test"]],
 remplace:"La séance sur la propagation de la lumière, souvent faite avec un schéma au tableau. Ici, l’image renversée est une énigme que l’élève résout lui-même avec des fils tendus.",
 phase:"Énigme, modélisation, puis expérimentation",
 gain:["L’image renversée surprend : elle crée le besoin d’expliquer.","Les fils tendus sont un modèle que l’élève manipule.","Le compromis netteté–luminosité se constate, il ne s’apprend pas par cœur.","Le lien avec la photographie et les arts plastiques est immédiat."],
 concep:[["« L’image est dans la boîte, comme une photo. »","Sans calque, on ne voit plus l’image : elle se forme là où la lumière arrive."],["« L’image est à l’envers parce que la boîte la retourne. »","Avec les fils tendus, on voit que les rayons se croisent dans le trou."],["« Plus le trou est grand, mieux on voit. »","Plus lumineux, mais plus flou : il faut choisir."]],
 relances:["Où arrive le rayon qui part du haut de la flèche ?","Que se passe-t-il si on agrandit le trou ?","Comment rendre l’image plus grande ?"],
 vocab:["source de lumière","objet éclairé","rayon","ligne droite","image","renversée","netteté","luminosité","sténopé"],
 trace:"<p><b>Schéma des rayons.</b></p><p>La lumière se propage en ligne droite. Les rayons qui viennent du haut de l’objet passent par le trou et arrivent en bas de l’écran : l’image est renversée. Un petit trou donne une image nette mais sombre, un grand trou une image lumineuse mais floue.</p>",
 aide:["Boîte déjà noircie et découpée.","Un seul trou à observer."],
 expert:["Fabriquer une boîte à tiroir et mesurer la taille de l’image selon la distance.","Prévoir la hauteur de l’image par un tracé à l’échelle."]},
"maison-eclairee":{
 notions:[["Sciences et technologie","Circuit fermé, boucle, interrupteur","Étapes 1 et 3"],["Sciences et technologie","Circuits en série et en dérivation","Étapes 1 et 2"],["Sciences et technologie","Sécurité électrique : court-circuit, jamais le secteur","Étape 5"],["Mathématiques","Tracer un plan, mesurer et reporter des longueurs","Étape 4"]],
 remplace:"La séance sur les circuits en série et en dérivation, souvent faite sur le plateau de test seulement. Ici, la maison pose une question réelle : allumer une pièce sans l’autre.",
 phase:"Investigation, puis réinvestissement dans un objet",
 gain:["« Une lampe grille » rend la différence série–dérivation utile.","Le plan de câblage oblige à raisonner en boucles.","Suivre la boucle avec le doigt devient la méthode de dépannage.","Le court-circuit est vu, nommé et évité."],
 concep:[["« La deuxième lampe éclaire moins parce que le courant s’use en chemin. »","En dérivation, les deux lampes éclairent autant : ce n’est pas la distance qui compte."],["« Un seul fil suffit pour allumer une lampe. »","Il faut une boucle complète, aller et retour jusqu’à la pile."],["« Un interrupteur coupe toute la maison. »","Il n’ouvre que la boucle sur laquelle il est placé."]],
 relances:["Suis la boucle avec ton doigt : passe-t-elle par les deux bornes ?","Que se passe-t-il si cette lampe grille ?","Où placer un interrupteur qui éteint tout ?"],
 vocab:["circuit","boucle","borne","interrupteur","ouvert","fermé","série","dérivation","court-circuit"],
 trace:"<p><b>Schéma normalisé de la maison.</b></p><p>Dans ma maison, les deux lampes sont en dérivation : chacune a sa boucle et son interrupteur. Si une lampe grille, l’autre reste allumée. En série, les lampes sont sur une seule boucle : si l’une s’éteint, l’autre aussi. Un fil qui relie directement les deux bornes de la pile fait un court-circuit : la pile chauffe.</p>",
 aide:["Plan de câblage fourni.","Une seule pièce à câbler, puis la seconde."],
 expert:["Ajouter un interrupteur général.","Câbler une troisième pièce."]},
"telegraphe":{
 notions:[["Sciences et technologie","Émetteur, récepteur, signal, information","Étapes 1 et 4"],["Sciences et technologie","Circuit électrique : une boucle peut être très longue","Étapes 1 et 2"],["Langage et français","Coder et décoder un message ; règles communes","Étapes 3 et 5"],["Mathématiques","Mesurer des durées ; comparer des résultats dans un tableau","Test"]],
 remplace:"La séance sur la transmission de l’information, souvent faite à partir de documents historiques. Ici, les élèves vivent le problème : sans code commun, le signal ne veut rien dire.",
 phase:"Situation-problème, puis amélioration",
 gain:["Le défi rend nécessaire le code commun.","Le temps et les erreurs mesurent la qualité du code.","Les règles de début, de fin et d’accusé de réception viennent des élèves.","Le code Morse prend sens après qu’on a inventé le sien."],
 concep:[["« L’électricité met du temps pour aller au bout du fil. »","On appuie et la lampe s’allume aussitôt, même à 10 m."],["« Il suffit d’allumer la lampe pour se comprendre. »","Sans code commun, le récepteur voit des éclairs mais ne comprend rien."],["« Un code, c’est forcément des lettres. »","Des éclairs courts et longs suffisent, si les deux équipes ont la même règle."]],
 relances:["Comment ton coéquipier sait-il qu’une lettre est finie ?","Pourquoi y a-t-il eu des erreurs ?","Comment savoir que le message est bien arrivé ?"],
 vocab:["émetteur","récepteur","signal","code","message","information","transmettre","circuit"],
 trace:"<p><b>Schéma de la ligne et feuille de code.</b></p><p>Pour transmettre une information à distance, il faut un émetteur, un récepteur, un signal et un code que les deux connaissent. Notre ligne transporte un signal électrique : quand on appuie sur le bouton, la lampe s’allume au bout du couloir. Avec une pause entre les lettres, nous avons fait moins d’erreurs.</p>",
 aide:["Code fourni pour cinq lettres.","Mot de trois lettres."],
 expert:["Ajouter une ligne retour pour l’accusé de réception.","Comparer son code au code Morse."]}
});


