 titre:"La file d’attente au lavabo",
 cycles:["1"], niv:"MS – GS", age:"4–6 ans", theme:["ecole","citoyennete","bienetre"], duree:"1h", mat:["sans"], demarche:"enquete", ouv:"semi",
